WITH exploded AS (SELECT id, service, log_ts, level, latency_ms, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, attr_value) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, SIZE(COLLECT_SET(k)) AS num_ks, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, MIN(latency_ms) AS min_latency_ms, COUNT_IF(service = 'search') AS search_events, COUNT_IF(k = 'region') AS region_events FROM exploded GROUP BY 1 ORDER BY span_minutes DESC
